import {Dialog, LinkButton} from '@primer/react'
import type React from 'react'
import {useRef} from 'react'
import {getReviewerMenuFocusTarget, useShowUpsellDialog} from './hooks'
import type {UpsellData} from './types'
import {getUpsellCopy} from './upsell-copy'

export const UpsellDialog: React.FC<UpsellData> = ({
  urls,
  plan,
  upsellPlan,
  isAdmin,
  quotaReset,
  overagesVisible,
  overagesEnabled,
  tokenBasedBilling,
}) => {
  const [showUpsell, setShowUpsell] = useShowUpsellDialog()
  const returnFocusRef = useRef<HTMLElement | null>(getReviewerMenuFocusTarget())
  const {body, overagesButtonText, title, upgradeButtonText} = getUpsellCopy({
    isAdmin,
    overagesEnabled,
    plan,
    quotaResetDate: quotaReset.dateTime,
    tokenBasedBilling,
    urls,
    upsellPlan,
  })

  if (!showUpsell) return null
  return (
    <Dialog
      title={title}
      subtitle={body}
      width="large"
      returnFocusRef={returnFocusRef}
      onClose={() => setShowUpsell(false)}
    >
      {(isAdmin || plan === 'individual') && (
        <div className="d-flex flex-justify-end gap-2 tmp-mt-4">
          {!!(urls.upsell && upsellPlan) && (
            <LinkButton target="_blank" rel="noopener noreferrer" href={urls.upsell} className="mr-2">
              {upgradeButtonText}
            </LinkButton>
          )}
          {overagesVisible && (
            <LinkButton
              target="_blank"
              rel="noopener noreferrer"
              href={overagesEnabled ? urls.billing : urls.policy}
              variant={urls.upsell ? 'invisible' : 'default'}
            >
              {overagesButtonText}
            </LinkButton>
          )}
        </div>
      )}
    </Dialog>
  )
}
