import {ErrorBoundary} from '@github-ui/react-core/error-boundary'
import type React from 'react'
import {useFetchUpsellData} from './hooks'
import {UpsellBanner} from './UpsellBanner'
import {UpsellDialog} from './UpsellDialog'

export interface UpsellProps {
  repositoryURL: string
  automaticReviewsEnabled: boolean
  isPullRequestOpen?: boolean
}

const UpsellDataLoader: React.FC<UpsellProps> = ({repositoryURL, automaticReviewsEnabled, isPullRequestOpen}) => {
  const data = useFetchUpsellData(repositoryURL)

  if (!data) return null
  return (
    <>
      <UpsellDialog {...data} />
      {!data.bannerDismissed && automaticReviewsEnabled && (
        <UpsellBanner repositoryURL={repositoryURL} isPullRequestOpen={isPullRequestOpen} {...data} />
      )}
    </>
  )
}

export const CopilotCodeReviewUpsell: React.FC<UpsellProps> = props => (
  <ErrorBoundary boundaryName="CopilotCodeReviewUpsell" fallback={null}>
    <UpsellDataLoader {...props} />
  </ErrorBoundary>
)
