import {ssrSafeDocument} from '@github-ui/ssr-utils'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {useCallback, useEffect, useState} from 'react'
import type {UpsellData} from './types'

const focusableElementSelector = [
  'summary',
  'a[href]',
  'button:not([disabled])',
  'input:not([disabled])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  '[tabindex]:not([tabindex="-1"])',
].join(',')

export const getReviewerMenuFocusTarget = () =>
  ssrSafeDocument?.getElementById('reviewers-select-menu')?.querySelector<HTMLElement>(focusableElementSelector) ?? null

const focusAfterDismiss = (container: HTMLElement | null | undefined) => {
  if (!container || !ssrSafeDocument?.activeElement || !container.contains(ssrSafeDocument.activeElement)) return

  const focusTarget =
    container.nextElementSibling?.querySelector<HTMLElement>(focusableElementSelector) ??
    container.previousElementSibling?.querySelector<HTMLElement>(focusableElementSelector) ??
    getReviewerMenuFocusTarget()

  focusTarget?.focus()
}

export const useFetchUpsellData = (repositoryURL: string) => {
  const [data, setData] = useState<UpsellData>()

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await reactFetchJSON(`${repositoryURL}/copilot_code_review_show_upsell`, {
          method: 'GET',
        })
        if (!response.ok) throw new Error()
        const body = await response.json()
        setData(body)
      } catch {
        // fail silently, nothing the user can do to fix it
      }
    }
    fetchData()
  }, [repositoryURL])

  return data
}

// determine if we should display the upsell dialog on reviewer selection
export const useShowUpsellDialog = () => {
  const [showUpsell, setShowUpsell] = useState(false)

  // listen for reviewer selections and check if they're ccr-quota-limited
  useEffect(() => {
    const menu = ssrSafeDocument?.getElementById('reviewers-select-menu')

    const listener = (e: Event) => {
      const target = e.target as HTMLElement | null

      if (
        !target ||
        !target.getAttribute('data-ccr-quota-limited') || // only check ccr-limited elements
        target.parentElement?.getAttribute('aria-checked') === 'true' // let users de-select the reviewer
      ) {
        return
      }

      e.preventDefault()
      e.stopPropagation()
      setShowUpsell(true)
      menu?.removeAttribute('open')
    }

    menu?.addEventListener('click', listener)
    return () => menu?.removeEventListener('click', listener)
  }, [])

  return [showUpsell, setShowUpsell] as const
}

export const useDismissUpsellBanner = (repositoryURL: string, key: string) => {
  const container = ssrSafeDocument?.getElementById('copilot-code-review-limits-banner')
  // Handles a bfcache bug that would mount multiple banners
  const [isDismissed, setDismissed] = useState(() => !!container?.hasChildNodes())

  const handleDismiss = useCallback(() => {
    focusAfterDismiss(container)
    setDismissed(true)
    try {
      reactFetchJSON(`${repositoryURL}/copilot_code_review_dismiss_upsell`, {
        method: 'POST',
        body: {key},
      })
    } catch {
      // fail silently, nothing the user can do to fix it
    }
  }, [repositoryURL, key, container])

  return {container, isDismissed, handleDismiss}
}
